<!--
 * 定时任务（列表页）
 *
 * @path apps\cronjob-web\src\views\job\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 定时任务（列表页）
 * <p>消费后端契约 JobController（src/api/job.ts，auto-generated by bash/gen-contract.py）的任务列表页：
 * 分页查询 page、暂停 pause / 恢复 resume（按 status 显示其一）、手动触发 trigger、删除 deleteApi，
 * 以及批量暂停/恢复/删除 batchPause / batchResume / batchDelete（勾选行组装 JobBatchDTO）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import {
  batchDelete,
  batchPause,
  batchResume,
  deleteApi,
  page,
  pause,
  resume,
  trigger,
} from '#/api/job';
import type { JobBatchDTO, JobVO } from '#/api/models';

import JobForm from './job-form.vue';

defineOptions({ name: 'JobManagement' });

const router = useRouter();
const { t } = useI18n();

/** 行类型：以真实契约 JobVO 为基础，status 由后端响应附带（契约模型未声明该字段） */
type JobRow = JobVO & { status?: string };

/** 判断任务当前是否为「已暂停」（兼容字符串/数字两种取值，未知值按运行中处理） */
function isPaused(row: JobRow): boolean {
  const status = row.status;
  return status === 'PAUSED' || status === 'DISABLED' || status === '0';
}

const gridOptions: VxeTableGridOptions<JobRow> = {
  columns: [
    { type: 'checkbox', width: 50 },
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'jobName', title: t('business.jobName'), width: 180 },
    { field: 'jobKey', title: '任务标识', width: 140 },
    { field: 'jobGroup', title: '分组', width: 100 },
    { field: 'cronExpression', title: 'Cron', width: 160 },
    { field: 'handler', title: '执行器', width: 140 },
    { field: 'jobType', title: t('business.jobType'), width: 100 },
    {
      field: 'status',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) => {
          const job = row as JobRow;
          return h(ElTag, { type: isPaused(job) ? 'info' : 'success' }, () =>
            isPaused(job) ? '已暂停' : '运行中',
          );
        },
      },
    },
    { field: 'jobRemark', title: '备注', width: 140 },
    {
      field: 'nextFireTime',
      title: '下次触发',
      width: 170,
      formatter: ({ cellValue }) => (cellValue ? String(cellValue).replace('T', ' ') : '-'),
    },
    {
      field: 'lastFireTime',
      title: '上次触发',
      width: 170,
      formatter: ({ cellValue }) => (cellValue ? String(cellValue).replace('T', ' ') : '-'),
    },
    { field: 'createdAt', title: t('common.createTime'), width: 160 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 300,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const job = row as JobRow;
          return h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(job) },
              () => t('common.edit'),
            ),
            isPaused(job)
              ? h(
                  ElButton,
                  { size: 'small', link: true, type: 'success', onClick: () => handleResume(job) },
                  () => '恢复',
                )
              : h(
                  ElButton,
                  { size: 'small', link: true, type: 'warning', onClick: () => handlePause(job) },
                  () => '暂停',
                ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleTrigger(job) },
              () => '触发',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'info', onClick: () => handleViewLog(job) },
              () => '日志',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(job) },
              () => t('common.delete'),
            ),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  checkboxConfig: { highlight: true },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const res = await page({
          pageNum: pageInfo.currentPage,
          size: pageInfo.pageSize,
          ...formValues,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'keyword',
        title: '关键词',
        itemRender: { name: 'Input', props: { placeholder: '任务名称/标识' } },
      },
      {
        field: 'group',
        title: '分组',
        itemRender: { name: 'Input', props: { placeholder: '分组' } },
      },
      {
        field: 'status',
        title: t('common.status'),
        itemRender: {
          name: 'Select',
          props: {
            clearable: true,
            options: [
              { label: '运行中', value: 'NORMAL' },
              { label: '已暂停', value: 'PAUSED' },
              { label: '已停止', value: 'STOPPED' },
              { label: '异常', value: 'ERROR' },
            ],
          },
        },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [JobFormModal, jobFormApi] = useYDSZModal({ connectedComponent: JobForm });

function handleAdd() {
  jobFormApi.open();
}

function handleEdit(row: JobRow) {
  jobFormApi.setData({ record: row });
  jobFormApi.open();
}

async function handlePause(row: JobRow) {
  if (!row.id) return;
  try {
    await pause({ id: row.id });
    ElMessage.success('已暂停');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleResume(row: JobRow) {
  if (!row.id) return;
  try {
    await resume({ id: row.id });
    ElMessage.success('已恢复');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleTrigger(row: JobRow) {
  if (!row.id) return;
  try {
    await trigger({ id: row.id }, {});
    ElMessage.success('触发成功');
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleDelete(row: JobRow) {
  try {
    await ElMessageBox.confirm(`确定删除「${row.jobName}」吗？`, '删除确认', { type: 'warning' });
    if (row.id) await deleteApi({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 跳转到执行日志页并预填任务标识筛选 */
function handleViewLog(row: JobRow) {
  router.push({ path: '/log/list', query: { jobKey: row.jobKey ?? '' } });
}

/** 收集勾选行的任务 ID（JobBatchDTO.jobIds），未勾选时给出提示 */
function getSelectedIds(): string[] {
  const rows = gridApi.grid.getCheckboxRecords() as JobRow[];
  const ids = rows.map((item) => item.id ?? '').filter((id) => id !== '');
  if (ids.length === 0) {
    ElMessage.warning('请先勾选需要操作的任务');
  }
  return ids;
}

async function handleBatchPause() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  const data: JobBatchDTO = { jobIds: ids };
  try {
    await batchPause(data);
    ElMessage.success('批量暂停成功');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleBatchResume() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  const data: JobBatchDTO = { jobIds: ids };
  try {
    await batchResume(data);
    ElMessage.success('批量恢复成功');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleBatchDelete() {
  const ids = getSelectedIds();
  if (ids.length === 0) return;
  try {
    await ElMessageBox.confirm(`确定批量删除选中的 ${ids.length} 个任务吗？`, '批量删除确认', {
      type: 'warning',
    });
    await batchDelete({ jobIds: ids } satisfies JobBatchDTO);
    ElMessage.success('批量删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('page.task')">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('common.create') }}</ElButton>
        <ElButton type="warning" plain @click="handleBatchPause">批量暂停</ElButton>
        <ElButton type="success" plain @click="handleBatchResume">批量恢复</ElButton>
        <ElButton type="danger" plain @click="handleBatchDelete">批量删除</ElButton>
      </template>
    </Grid>
    <JobFormModal @success="gridApi.query()" />
  </Page>
</template>
